void PndLmdDataReader::setBeam(double lab_momentum) {
  beam = TLorentzVector(
      0, 0, lab_momentum,
      sqrt(pow(lab_momentum, 2.0) + pow(pdg->GetParticle(-2212)->Mass(), 2.0)));
}

void PndLmdDataReader::read() {
  std::vector<PndLmdAbstractData *> lmd_vec = combineAllRegisteredDataObjects();

  if (0 == lmd_vec.size()) {
    std::cout << "No data or acceptance objects were registered, hence no data "
                 "can be filled."
                 " Please register objects via the register methods of this "
                 "helper class"
              << std::endl;
    return;
  }

  initDataStream();

  int temp_num_events = getEntries();
  int num_events = 0;

  // all data objects initialized with -1 as number of events
  // should be filled with all found data -> adjust that now
  for (unsigned int i = 0; i < lmd_vec.size(); i++) {
    if (0 == lmd_vec[i]->getNumEvents()) {
      lmd_vec[i]->setNumEvents(temp_num_events);
    }
  }

  // get maximum event number for all registered data objects
  for (unsigned int i = 0; i < lmd_vec.size(); i++) {
    if (num_events < lmd_vec[i]->getNumEvents())
      num_events = lmd_vec[i]->getNumEvents();
    else if (lmd_vec[i]->getNumEvents() == -1) {
      num_events = temp_num_events;
      break;
    }
    if (num_events > temp_num_events) {
      num_events = temp_num_events;
      break;
    }
  }
  // now run over all registered data objects once again and adjust
  // the number of events accordingly
  for (unsigned int i = 0; i < lmd_vec.size(); i++) {
    if (num_events < lmd_vec[i]->getNumEvents())
      lmd_vec[i]->setNumEvents(num_events);
    else if (lmd_vec[i]->getNumEvents() == -1) {
      lmd_vec[i]->setNumEvents(num_events);
    }
  }
  int min_num_events = getNextMinEventIndex(lmd_vec);

  std::cout << "Processing " << num_events << " events" << std::endl;

  boost::progress_display show_progress(num_events);

  for (Int_t j = 0; j < num_events; j++) {
    // this check is to remove the data registered data objects for which
    // the event count has reached the specified value
    if (j == min_num_events) {
      // remove the data objects that hit their specified event count
      removeFinished(lmd_vec, j);
      // adjust the minimum number of events to the remaining data objects
      min_num_events = getNextMinEventIndex(lmd_vec);
    }

    std::vector<Lmd::Data::TrackPairInfo> track_pair_infos = getEntry(j);
    for (auto const &trk_pair_info : track_pair_infos) {
      fillData(trk_pair_info);
    }
    ++show_progress;
  }

  cleanup();
}

void PndLmdDataReader::fillData(const Lmd::Data::TrackPairInfo &track_info) {
  if (isGoodTrack(track_info)) {
    std::vector<double> data(4);
    auto const &mom_mc = track_info.MCIP.Momentum;
    auto const &mom_rec = track_info.RecoIP.Momentum;
    data[0] = mom_rec[0] / mom_rec[2];
    data[1] = mom_rec[1] / mom_rec[2];
    data[2] = mom_mc[0] / mom_mc[2];
    data[3] = mom_mc[1] / mom_mc[2];

    for (unsigned int i = 0; i < registered_map_data.size(); ++i) {
      registered_map_data[i]->addData(data);
    }
  }

  for (unsigned int i = 0; i < registered_data.size(); i++) {
    if (!skipDataObject(registered_data[i], track_info)) {
      if (successfullyPassedFilters(registered_data[i], track_info)) {
        if (registered_data[i]->getSecondaryDimension().is_active) {
          registered_data[i]->addData(
              getTrackParameterValue(track_info,
                                     registered_data[i]->getPrimaryDimension()),
              getTrackParameterValue(
                  track_info, registered_data[i]->getSecondaryDimension()));
        } else {
          registered_data[i]->addData(getTrackParameterValue(
              track_info, registered_data[i]->getPrimaryDimension()));
        }
      }
    }
  }
  for (unsigned int i = 0; i < registered_acceptances.size(); i++) {
    bool track_accepted = wasReconstructed(track_info);
    if (track_info.IsSecondary) {
        continue;
    }
    // skip tracks that do not pass the filters
    if (successfullyPassedFilters(registered_acceptances[i], track_info)) {
      if (registered_acceptances[i]->getSecondaryDimension().is_active) {
        registered_acceptances[i]->addData(
            track_accepted,
            getTrackParameterValue(
                track_info, registered_acceptances[i]->getPrimaryDimension()),
            getTrackParameterValue(
                track_info,
                registered_acceptances[i]->getSecondaryDimension()));
      } else {
        registered_acceptances[i]->addData(
            track_accepted,
            getTrackParameterValue(
                track_info, registered_acceptances[i]->getPrimaryDimension()));
      }
    }
  }
}

bool PndLmdDataReader::isGoodTrack(
    const Lmd::Data::TrackPairInfo &track_info) const {
  return (track_info.IsReconstructedAtIP);
}

bool PndLmdDataReader::wasReconstructed(
    const Lmd::Data::TrackPairInfo &track_info) const {
  return (track_info.IsReconstructedAtIP);
}

bool PndLmdDataReader::skipDataObject(
    const PndLmdAbstractData *data,
    const Lmd::Data::TrackPairInfo &track_info) const {
  // if it was not reconstructed and this information is required
  if (!wasReconstructed(track_info)) {
    if (LumiFit::RECO ==
        data->getPrimaryDimension().dimension_options.track_type) {
      return true;
    } else if (LumiFit::MC_ACC ==
                   data->getPrimaryDimension().dimension_options.track_type ||
               LumiFit::DIFF_RECO_MC ==
                   data->getPrimaryDimension().dimension_options.track_type) {
      return true;
    }
    if (data->getSecondaryDimension().is_active) {
      if (LumiFit::RECO ==
          data->getSecondaryDimension().dimension_options.track_type)
        return true;
      else if (LumiFit::MC_ACC ==
                   data->getSecondaryDimension().dimension_options.track_type ||
               LumiFit::DIFF_RECO_MC ==
                   data->getSecondaryDimension().dimension_options.track_type) {
        return true;
      }
    }
  }
  if (LumiFit::MC == data->getPrimaryDimension().dimension_options.track_type) {
    if (track_info.IsSecondary)
      return true;
  }
  return false;
}

bool PndLmdDataReader::successfullyPassedFilters(
    const PndLmdAbstractData *data,
    const Lmd::Data::TrackPairInfo &track_info) const {
  // if it fails to pass a filter
  const std::set<LumiFit::LmdDimension> &selection_dimensions(
      data->getSelectorSet());
  std::set<LumiFit::LmdDimension>::iterator selection_dimension_iterator =
      selection_dimensions.begin();
  while (selection_dimension_iterator != selection_dimensions.end()) {
    if (false ==
        selection_dimension_iterator->dimension_range.isDataWithinRange(
            getTrackParameterValue(track_info,
                                   *selection_dimension_iterator))) {
      return false;
    }
    ++selection_dimension_iterator;
  }
  return true;
}

double PndLmdDataReader::getTrackParameterValue(
    const Lmd::Data::TrackPairInfo &track_info,
    const LumiFit::LmdDimension &lmd_dim) const {
  TVector3 pos(0.0, 0.0, 0.0);
  TVector3 mom(0.0, 0.0, 1.0);
  double theta(0.0);
  double phi(0.0);
  double theta_x(0.0);
  double theta_y(0.0);

  if (lmd_dim.dimension_options.dimension_type == LumiFit::PARTICLE_ID) {
    return 1.0 * track_info.PDGCode;
  }

  if (lmd_dim.dimension_options.dimension_type == LumiFit::SECONDARY) {
    return 1.0 * track_info.IsSecondary;
  }

  if (lmd_dim.dimension_options.track_type == LumiFit::MC ||
      lmd_dim.dimension_options.track_type == LumiFit::MC_ACC) {
    if (lmd_dim.dimension_options.track_param_type == LumiFit::IP) {
      auto mc_pos = track_info.MCIP.Position;
      pos.SetXYZ(mc_pos[0], mc_pos[1], mc_pos[2]);
      auto mc_mom = track_info.MCIP.Momentum;
      mom.SetXYZ(mc_mom[0], mc_mom[1], mc_mom[2]);
    } else if (lmd_dim.dimension_options.track_param_type == LumiFit::LMD) {
      auto mc_pos = track_info.MCLMD.Position;
      pos.SetXYZ(mc_pos[0], mc_pos[1], mc_pos[2]);
      auto mc_mom = track_info.MCLMD.Momentum;
      mom.SetXYZ(mc_mom[0], mc_mom[1], mc_mom[2]);
    }
    theta = mom.Theta();
    phi = mom.Phi();
    theta_x = mom.X() / mom.Z();
    theta_y = mom.Y() / mom.Z();
  } else if (lmd_dim.dimension_options.track_type == LumiFit::RECO) {
    if (lmd_dim.dimension_options.track_param_type == LumiFit::IP) {
      auto reco_pos = track_info.RecoIP.Position;
      pos.SetXYZ(reco_pos[0], reco_pos[1], reco_pos[2]);
      auto reco_mom = track_info.RecoIP.Momentum;
      mom.SetXYZ(reco_mom[0], reco_mom[1], reco_mom[2]);
    } else if (lmd_dim.dimension_options.track_param_type == LumiFit::LMD) {
      auto reco_pos = track_info.RecoLMD.Position;
      pos.SetXYZ(reco_pos[0], reco_pos[1], reco_pos[2]);
      auto reco_mom = track_info.RecoLMD.Momentum;
      mom.SetXYZ(reco_mom[0], reco_mom[1], reco_mom[2]);
    }
    theta = mom.Theta();
    phi = mom.Phi();
    theta_x = mom.X() / mom.Z();
    theta_y = mom.Y() / mom.Z();
  }

  else if (lmd_dim.dimension_options.track_type == LumiFit::DIFF_RECO_MC) {
    TVector3 mcpos(0.0, 0.0, 0.0);
    TVector3 mcmom(0.0, 0.0, 0.0);
    if (lmd_dim.dimension_options.track_param_type == LumiFit::IP) {
      auto mc_pos = track_info.MCIP.Position;
      mcpos.SetXYZ(mc_pos[0], mc_pos[1], mc_pos[2]);
      auto mc_mom = track_info.MCIP.Momentum;
      mcmom.SetXYZ(mc_mom[0], mc_mom[1], mc_mom[2]);
      auto reco_pos = track_info.RecoIP.Position;
      pos.SetXYZ(reco_pos[0], reco_pos[1], reco_pos[2]);
      auto reco_mom = track_info.RecoIP.Momentum;
      mom.SetXYZ(reco_mom[0], reco_mom[1], reco_mom[2]);
    } else if (lmd_dim.dimension_options.track_param_type == LumiFit::LMD) {
      auto mc_pos = track_info.MCLMD.Position;
      mcpos.SetXYZ(mc_pos[0], mc_pos[1], mc_pos[2]);
      auto mc_mom = track_info.MCLMD.Momentum;
      mcmom.SetXYZ(mc_mom[0], mc_mom[1], mc_mom[2]);
      auto reco_pos = track_info.RecoLMD.Position;
      pos.SetXYZ(reco_pos[0], reco_pos[1], reco_pos[2]);
      auto reco_mom = track_info.RecoLMD.Momentum;
      mom.SetXYZ(reco_mom[0], reco_mom[1], reco_mom[2]);
    }

    pos.SetXYZ(pos.X() - mcpos.X(), pos.Y() - mcpos.Y(), pos.Z() - mcpos.Z());
    theta = mom.Theta() - mcmom.Theta();
    phi = mom.Phi() - mcmom.Phi();
    if (phi > TMath::Pi())
      phi = phi - 2.0 * TMath::Pi();
    if (phi < TMath::Pi())
      phi = phi + 2.0 * TMath::Pi();

    theta_x = mom.X() / mom.Z() - mcmom.X() / mcmom.Z();
    theta_y = mom.Y() / mom.Z() - mcmom.Y() / mcmom.Z();
  }

  if (lmd_dim.dimension_options.dimension_type == LumiFit::X) {
    return pos.X();
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::Y) {
    return pos.Y();
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::Z) {
    return pos.Z();
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::T) {
    TLorentzVector track(mom, sqrt(pow(mom.Mag(), 2.0) +
                                   pow(pdg->GetParticle(-2212)->Mass(), 2.0)));
    return -(track - beam).M2();
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::THETA_X) {
    return theta_x;
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::THETA_Y) {
    return theta_y;
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::THETA) {
    return theta;
  } else if (lmd_dim.dimension_options.dimension_type == LumiFit::PHI) {
    return phi;
  } else
    return 0.0;
}

void createLmdFitData(const std::string &input_dir_path,
                      const std::string &filelist_path,
                      const std::string &output_dir_path,
                      const std::string &config_file_url, const double mom,
                      std::string &data_types, int num_events,
                      const double total_elastic_cross_section) {
  std::cout << "Running LmdFit data reader....\n";

  PndLmdRuntimeConfiguration &lmd_runtime_config =
      PndLmdRuntimeConfiguration::Instance();

  // set paths and general infos first
  lmd_runtime_config.setMomentum(mom);
  lmd_runtime_config.setNumEvents(num_events);
  lmd_runtime_config.setTotalElasticCrossSection(total_elastic_cross_section);

  lmd_runtime_config.setRawDataDirectory(input_dir_path);
  if (filelist_path != "")
    lmd_runtime_config.setRawDataFilelistPath(filelist_path);
  lmd_runtime_config.setDataOutputDirectory(output_dir_path);

  // set general config path
  lmd_runtime_config.setGeneralConfigDirectory(config_file_url);

  // read data parameter config
  boost::filesystem::path data_config_path(config_file_url);
  lmd_runtime_config.readDataConfig(data_config_path.filename().string());

  PndLmdDataFacade data_facade;

  PndLmdCombinedDataReader data_reader;
  if (!boost::filesystem::exists(lmd_runtime_config.getRawDataFilelistPath()))
    data_reader.addFilePath(lmd_runtime_config.getRawDataDirectory().string() +
                            "/Lumi_TrksQA*.root");
  else {
    data_reader.addFileList(
        lmd_runtime_config.getRawDataFilelistPath().string());
  }

  data_facade.createAndFillDataBundles(data_types, data_reader);

  std::cout << std::endl << std::endl;
  std::cout << "Application finished successfully." << std::endl;
  std::cout << std::endl;

  // ------------------------------------------------------------------------
}

#include "PndLmdCombinedDataReader.h"
#include "PndLmdTrackQ.h"

PndLmdCombinedDataReader::PndLmdCombinedDataReader()
    : rel_momentum_deviation_threshold(0.0003), data_tree("pndsim"),
      filtered_track_array("PndLmdTrackQ", 100) {
  track_array = 0;
}

PndLmdCombinedDataReader::~PndLmdCombinedDataReader() {}

unsigned int PndLmdCombinedDataReader::getEntries() const {
  return data_tree.GetEntries();
}

void PndLmdCombinedDataReader::initDataStream() {
  for (unsigned int i = 0; i < file_paths.size(); i++)
    data_tree.Add(file_paths[i]);

  track_array = new TClonesArray("PndLmdTrackQ");
  data_tree.SetBranchAddress("LMDTrackQ", &track_array);
  data_tree.SetBranchStatus("LMDTrackQ*", 1);
}

void PndLmdCombinedDataReader::clearDataStream() {}

std::vector<Lmd::Data::TrackPairInfo>
PndLmdCombinedDataReader::getEntry(unsigned int i) {
  data_tree.GetEntry(i);
  filtered_track_array.Clear();
  unsigned int good_track_counter = 0;

  std::vector<Lmd::Data::TrackPairInfo> track_pairs;

  // loop over track array
  for (Int_t iN = 0; iN < track_array->GetEntries(); iN++) {
    PndLmdTrackQ *track = (PndLmdTrackQ *)track_array->At(iN);
    TVector3 temp_vec;

    Lmd::Data::TrackPairInfo track_info;
    if (0 <= track->GetTrkRecStatus()) {
      track_info.IsReconstructedAtLmd = true;
      track_info.IsReconstructedAtIP = true;
    }
    if (-10 == track->GetTrkRecStatus())
      track_info.IsReconstructedAtLmd = true;
    if (0 <= track->GetSecondary())
      track_info.IsSecondary = true;

    if (track_info.IsReconstructedAtIP) {
      track->GetIPpoint(temp_vec);
      track_info.RecoIP.Position = {temp_vec.X(), temp_vec.Y(), temp_vec.Z()};
      TVector3 mom;
      mom.SetMagThetaPhi(track->GetIPmom(), track->GetIPtheta(),
                         track->GetIPphi());
      track_info.RecoIP.Momentum = {mom.X(), mom.Y(), mom.Z()};
    }

    if (track_info.IsReconstructedAtLmd) {
      track->GetLMDpoint(temp_vec);
      track_info.RecoLMD.Position = {temp_vec.X(), temp_vec.Y(), temp_vec.Z()};
      TVector3 mom;
      mom.SetMagThetaPhi(track->GetLMDphi(), track->GetIPtheta(),
                         track->GetIPphi());
      track_info.RecoLMD.Momentum = {mom.X(), mom.Y(), mom.Z()};
    }

    track->GetMCpoint(temp_vec);
    track_info.MCIP.Position = {temp_vec.X(), temp_vec.Y(), temp_vec.Z()};
    TVector3 mom;
    mom.SetMagThetaPhi(track->GetMCmom(), track->GetMCtheta(),
                       track->GetMCphi());
    track_info.MCIP.Momentum = {mom.X(), mom.Y(), mom.Z()};

    track->GetMCpointLMD(temp_vec);
    track_info.MCLMD.Position = {temp_vec.X(), temp_vec.Y(), temp_vec.Z()};
    mom.SetMagThetaPhi(track->GetMCmomLMD(), track->GetMCthetaLMD(),
                       track->GetMCphiLMD());
    track_info.MCLMD.Momentum = {mom.X(), mom.Y(), mom.Z()};

    track_pairs.push_back(track_info);
  }

  return track_pairs;
}

/*
 * This is the application that generates the Lmd data objects, which can be
 * used to determine the luminosity. This application primarily uses the
 * #PndLmdDataFacade class to easily create lmd fit data objects and fill them
 * with data. General information about the individual classes of the LmdFit
 * framework can be found in the doxygen manual.
 * Run it with argument -h to get running help:
 *
 * ./createLumiFitData -h
 */

#include "ui/PndLmdDataFacade.h"
#include "ui/PndLmdRuntimeConfiguration.h"

#include <iostream>
#include <string>

using std::cerr;
using std::cout;
using std::endl;
using std::string;

void createLmdFitData(const std::string &input_dir_path,
                      const std::string &filelist_path,
                      const std::string &output_dir_path,
                      const std::string &config_file_url, const double mom,
                      std::string &data_types, int num_events,
                      const double total_elastic_cross_section) {
  std::cout << "Running LmdFit data reader....\n";

  PndLmdRuntimeConfiguration &lmd_runtime_config =
      PndLmdRuntimeConfiguration::Instance();

  // set paths and general infos first
  lmd_runtime_config.setMomentum(mom);
  lmd_runtime_config.setNumEvents(num_events);
  lmd_runtime_config.setTotalElasticCrossSection(total_elastic_cross_section);

  lmd_runtime_config.setRawDataDirectory(input_dir_path);
  if (filelist_path != "")
    lmd_runtime_config.setRawDataFilelistPath(filelist_path);
  lmd_runtime_config.setDataOutputDirectory(output_dir_path);

  // set general config path
  lmd_runtime_config.setGeneralConfigDirectory(config_file_url);

  // read data parameter config
  boost::filesystem::path data_config_path(config_file_url);
  lmd_runtime_config.readDataConfig(data_config_path.filename().string());

  PndLmdDataFacade data_facade;

  PndLmdCombinedDataReader data_reader;
  if (!boost::filesystem::exists(lmd_runtime_config.getRawDataFilelistPath()))
    data_reader.addFilePath(lmd_runtime_config.getRawDataDirectory().string() +
                            "/Lumi_TrksQA*.root");
  else {
    data_reader.addFileList(
        lmd_runtime_config.getRawDataFilelistPath().string());
  }

  data_facade.createAndFillDataBundles(data_types, data_reader);

  std::cout << std::endl << std::endl;
  std::cout << "Application finished successfully." << std::endl;
  std::cout << std::endl;

  // ------------------------------------------------------------------------
}

void displayInfo() {
  // display info
  std::cout << "Required arguments are: " << std::endl;
  std::cout << "-m [pbar momentum]" << std::endl;
  std::cout << "-t [type of data to create] (a = angular, e = efficiency, r = "
               "resolution, v = vertex)"
            << std::endl;
  std::cout << "-d [input directory path]" << std::endl;
  std::cout << "-c [data config file path]" << std::endl;
  std::cout << "Optional arguments are: " << std::endl;
  std::cout << "-f [filelist path]" << std::endl;
  std::cout << "-o [output directory path]" << std::endl;
  std::cout << "-n [number of events to process] "
               "(default 0: all data found will be processed)"
            << std::endl;
  std::cout << "-e [total elastic cross section]" << std::endl;
  std::cout << std::endl;
  std::cout
      << "Note: The type value is specified as a string, in which the 4 "
         "letters\n"
         "a, e, r, v can be concatenated freely. For just a single data type\n"
         "the values should be a, e, r, v. For a combination i.e\n"
         "angular vertex data, one should use av or va. Other additional\n"
         "characters will be ignored, so can be specified without any effect!\n"
         "\n"
         "the parameter -e is the total elastic cross section to estimate\n"
         "the generated luminosity. In case you do NOT specify this value it\n"
         "will be set to -1.0 and there is no performance validation "
         "possible,\n"
         "but only luminosity determination. This should be the case only for\n"
         "real data!"
      << std::endl;
}

bool checkDataType(std::string &data_type) {
  bool is_valid = false;
  if (data_type.find("a") != std::string::npos) {
    is_valid = true;
  } else if (data_type.find("e") != std::string::npos) {
    is_valid = true;
  } else if (data_type.find("r") != std::string::npos) {
    is_valid = true;
  } else if (data_type.find("v") != std::string::npos) {
    is_valid = true;
  }
  return is_valid;
}

int main(int argc, char *argv[]) {
  bool is_mom_set = false, is_cross_section_set = false,
       is_data_path_set = false, is_filelist_path_set = false,
       is_output_data_path_set = false, is_config_file_path_set = false;
  double momentum = -1.0;
  std::string data_type = "";
  unsigned int num_events = 0;
  double cross_section = 1.0;
  std::string data_path;
  std::string config_file_path;
  std::string output_dir_path;
  std::string filelist_path("");
  int c;

  while ((c = getopt(argc, argv, "hm:f:o:n:t:d:c:e:")) != -1) {
    switch (c) {
    case 'm':
      momentum = atof(optarg);
      is_mom_set = true;
      break;
    case 'f':
      filelist_path = optarg;
      is_filelist_path_set = true;
      break;
    case 'o':
      output_dir_path = optarg;
      is_output_data_path_set = true;
      break;
    case 'n':
      num_events = atoi(optarg);
      break;
    case 'e':
      cross_section = atof(optarg);
      is_cross_section_set = true;
      break;
    case 't':
      data_type = optarg;
      break;
    case 'd':
      data_path = optarg;
      is_data_path_set = true;
      break;
    case 'c':
      config_file_path = optarg;
      is_config_file_path_set = true;
      break;
    case '?':
      if (optopt == 't' || optopt == 'd' || optopt == 'm' || optopt == 'n' ||
          optopt == 'c' || optopt == 'e')
        std::cerr << "Option -" << optopt << " requires an argument."
                  << std::endl;
      else if (isprint(optopt))
        std::cerr << "Unknown option -" << optopt << "." << std::endl;
      else
        std::cerr << "Unknown option character" << optopt << "." << std::endl;
      return 1;
    case 'h':
      displayInfo();
      return 1;
    default:
      return 1;
    }
  }

  bool skip_program = false;
  if (!is_output_data_path_set && is_filelist_path_set) {
    std::cerr << "Please specify an output directory via the -o option when "
                 "using a filelist path as input!"
              << std::endl;
    skip_program = true;
  }
  if (!(checkDataType(data_type) && is_mom_set && is_data_path_set))
    skip_program = true;

  if (skip_program)
    displayInfo();
  else {
    if (!is_output_data_path_set)
      output_dir_path = data_path;
    createLmdFitData(data_path, filelist_path, output_dir_path,
                     config_file_path, momentum, data_type, num_events,
                     cross_section);

    return 0;
  }
}

