void PndPidCorrelator::Finish() {
  //---
  if (fDebugMode)
  {
    //TFile *r = TFile::Open(sDir+sFile,"RECREATE");
    r->cd();
    tofCorr->Write();
    ftofCorr->Write();
    emcCorr->Write();
    fscCorr->Write();
    mdtCorr->Write();
    drcCorr->Write();
    dskCorr->Write();

    r->Save();

    tofCorr->Delete();
    ftofCorr->Delete();
    emcCorr->Delete();
    fscCorr->Delete();
    mdtCorr->Delete();
    drcCorr->Delete();
    dskCorr->Delete();

    tofCorr = 0;
    ftofCorr = 0;
    emcCorr = 0;
    fscCorr = 0;
    mdtCorr = 0;
    drcCorr = 0;
    dskCorr = 0;

    r->Close();
    r->Delete();
  }

}
